def load_source(path):
    x=json.load(open(os.path.join(ROOT,path)))
    post=x.get("post",{})
    refs={"post": ((post.get("title") or "") + "\n" + (post.get("selftext") or ""))}
    for c in x.get("comments",[]): refs[c["id"]]=c.get("body") or ""
    return x,refs

def quote(refs, ref, needle=None):
    body=refs[ref]
    if needle is None: return body
    assert needle in body,(ref,needle)
    return needle

def episode(thread, author, refs, stage, coarse, desc, location=None, scope="geography_unresolved", utility=None,
            timing=None,costs=None,effort=None,actions=None,loc_ev=None,county=None,mass=1.0):
    return {"thread":thread,"author":author,"decision_case_id":f"{thread}__{author}",
      "lifecycle_stage":stage,"lifecycle_coarse":coarse,"inference_scope":scope,
      "location":location or {},"location_evidence":loc_ev or [],"county_weights":county or {},
      "unassigned_geography_mass":mass,"utility":utility,"source_refs":refs,
      "timing":timing or [],"costs":costs or [],"effort":effort or [],
      "non_registry_actions":actions or [],"descriptive":desc if isinstance(desc,list) else [desc]}

def act(actor, action, status, ref, q): return {"actor":actor,"action":action,"status":status,"refs":[ref],"quote":q}
def cost(item,value,unit,ref,q,direction="paid_by_applicant",note=None):
    z={"item":item,"value":value,"unit":unit,"direction":direction,"refs":[ref],"quote":q}
    if note:z["note"]=note
    return z
def timing(clock,unit,ref,q,censoring,start=None,end=None,value=None,lower=None,upper=None,note=None,dates=None):
    z={"clock":clock,"start_event":start,"end_event":end,"unit":unit,"censoring":censoring,"refs":[ref],"quote":q,"supported_event_dates":dates or []}
    if value is not None:z["value"]=value
    if lower is not None:z["lower"]=lower
    if upper is not None:z["upper"]=upper
    if note:z["note"]=note
    return z

