    manifest={"schema_version":"solar-packet-manifest/1","packet_id":pid,"inputs":[{"path":s["source_path"],"sha256":s["sha256"]} for s in reservation["sources"]]+[{"path":os.path.join(pdir,"source_text.txt"),"sha256":sha(os.path.join(pdir,"source_text.txt"))}],"outputs":[{"path":os.path.join(pdir,n),"sha256":sha(os.path.join(pdir,n))} for n in ["decisions.json","coverage.json","timing_staged.json"]],"reader":"/root/solar_burden_sol","model":"gpt-6-sol","started_at":reservation.get("reading_started_at"),"finished_at":datetime.now(timezone.utc).isoformat(),"counts":counts,"assumptions":["Every held comment fully read.","Quoted, forecast, offered, or declined money is descriptive rather than incurred cost.","Unknown geography retained; no location inferred from username or installer address.","Physical-installation, repair, cancellation, deposit, activation, and site-survey boundaries remain null when outside the fixed event vocabulary; physically installed is never treated as final inspection."],"no_synthetic_truth_access":True,"staged_not_model_consumed":True}
